MATCH (item:PlantItem {tag: "TK-13-5"})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'T-8-4'}), (b:PlantItem {tag: 'T-8-5'})
RETURN a.tag AS source_tag, b.tag AS destination_tag,
       EXISTS { MATCH (a)-[:send_to*1..]->(b) } AS can_reach;

MATCH (s:PlantItem {tag: "TK-6-2"}), (t:PlantItem {tag: "V-6-5"})
RETURN s.tag AS source_tag, t.tag AS target_tag,
       EXISTS {
         MATCH p = (s)-[:send_to*1..]->(t)
         WHERE all(n IN nodes(p) WHERE coalesce(n.tag, "") <> "GV-6-7")
       } AS can_flow

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: "P-9-10"})
WHERE NOT EXISTS {
  MATCH ()-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag

MATCH (start:PlantItem {tag: 'P-13-1'})-[:send_to*1..]->(downstream:PlantItem)
WHERE downstream.unit_id <> start.unit_id
RETURN count(DISTINCT downstream.unit_id) AS other_units;
